INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65308657', 65308657, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'KANTOR PUSAT BADAN PERTANAHAN NASIONAL REPUBLIK INDONESIA', 'Monitoring Isu/Pemberitaan di Media', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 900000000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '2 PKT', 'Dalam pelaksanaan monitoring dilakukan dalam sebuah sistem aplikasi yang memuat banyak data dan informasi pemberitaan yang ada pada media online, media cetak, media digital, sosial media (Facebook, YouTube, Twitter, Instagram, dan Tiktok), blog, aplikasi review (Google App & App Store) dan forum-forum diskusi. Sistem aplikasi yang digunakan dapat dioperasikan dan difungsikan dengan optimal sesuai dengan kebutuhan pengguna. Dalam tahap ini sistem aplikasi dapat disesuaikan dengan kebutuhan pengguna untuk memberikan kemudahan dalam pengoperasiannya. Pengumpulan Data Media Analytics merupakan sebuah kegiatan dalam sistem aplikasi untuk mengumpulkan berbagai data (konten) dari berbagai media. Media yang menjadi sumber dapat berupa media online, media cetak, media digital (TV), sosial media (Facebook, YouTube, Twitter, Instagram, dan Tiktok), blog, aplikasi review (Google App & App Store) dan forum-forum diskusi yang relevan dengan topik yang diuraikan. Untuk mengumpulkan data, biasanya digunakan sebuah kata kunci (keyword) yang spesifik untuk menentukan data apa yang akan diambil dan juga media apa saja yang akan dipakai sebagai sumber data. Ekstraksi Data Dengan memanfaatkan fitur media analytics untuk melakukan pengukuran secara otomatis. Pengukuran yang dilakukan meliputi pengukuran performa reputasi atau informasi-informasi tertentu. Pengukuran ini didapatkan dengan melihat sentimen percakapan dan berita untuk kemudian diambil ekstraksi topiknya', 'Merujuk pada data-data yang dikumpulkan untuk dapat digunakan berbagai keperluan. Uraian data untuk melakukan filter, mengelompokkan data, dan uraian lebih lanjut. uraian dan fitur yang dibutuhkan meliputi: Formal Media Monitoring: ● Akses User Admin ● Akses User 34 Kantor Wilayah Provinsi BPN ● Distribusi Data ● Uraian Sentimen ● Pergerakan ekspos berita dan cuitan ● Tokoh, Influencer dan Buzzer sosok popular di media ● Isu strategis perbincangan di media ● PR Value dan Ad Value ● Early Warning System (Sistem Deteksi Dini) ● Geomaps ● Spokeperson ● Top Issue ● Top 10 Media ● Media Visibility ● Coverage Tone ● Trackback Data ● Voice to Text ● Running Text (TV & Radio) ● Validasi Data ● Alert pemberitaan negative melalui Telegram, Email dan WhatsApp ● Penambahan dan Perbaruan data Keyword tidak terbatas Sosial Media Monitoring: ● Akses User Admin ● Early Warning System (Sistem Deteksi Dini) ● SNA (Social Network Analytics) ● Comment Data Crawling ● LIVE ● Deteksi Entitas ● Topic Cloud ● Unlimited Stream ● Alert pemberitaan negative melalui email ● Deteksi Emosi ● Top Authors/Akun', 180000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2060306);
