INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65311944', 65311944, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Rencana Proyek Kerja Sama Pemerintah dengan Badan Usaha/Public-Private Partnership Book (PPP Book)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 134000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Mereviu dan menganalisis dokumen perencanaan/penyiapan dan dokumen pendukung proyek KPBU yang diusulkan oleh calon PJPK dalam hal penyusunan Daftar Rencana KPBU/PPP Book; 1. Mereviu dan menganalisis dokumen perencanaan/penyiapan dan dokumen pendukung proyek KPBU yang diusulkan oleh calon PJPK dalam hal penyusunan Daftar Rencana KPBU/PPP Book; 2. Melakukan analisis dampak sektoral atas proyek yang diusulkan oleh calon PJPK dengan direktorat sektor di Kementerian PPN/Bappenas untuk mendapatkan rekomendasi pencantuman proyek dalam Daftar Rencana KPBU/PPP Book; 3. Melakukan evaluasi atas proyek KPBU yang sebelumnya sudah tercantum dalam Daftar Rencana KPBU/PPP Book selama kurang dari 2 tahun dan proyek KPBU yang mengalami kenaikan status; 4. Maelakukan evaluasi atas proyek KPBU yang sebelumnya sudah tercantum dalam Daftar Rencana KPBU/PPP Book selama 2 tahun atau lebih; 5. Melaksanakan rapat konfirmasi dengan Kantor Bersama KPBU atas penyusunan daftar proyek awal yang akan dicantumkan dalam Daftar Rencana KPBU/PPP Book; 6. Menyiapkan data dukung proyek dalam rangka penyusunan draft Keputusan Menteri PPN/Kepala Bappenas tentang Penetapan Daftar Rencana KPBU dan PPP Book; 7. Melakukan koordinasi lintas sektor dengan kementerian/lembaga, pemerintah daerah, dan mitra strategis lainnya dalam rangka harmonisasi perencanaan dan pengembangan Proyek Strategis Nasional; dan 8. Melakukan koordinasi dengan stakeholder tidak terbatas pada Kantor Bersama KPBU dan PJPK mengenai progres proyek KPBU sektor pekerjaan umum dan perumahan maupun eksplorasi skema pembiayaan KPBU/pembiayaan alternatif lainnya.', '1. Pendidikan minimal Sarjana (S2) di bidang teknik, yang dibuktikan dengan ijazah; 2. Memiliki pengalaman minimal 3 (tiga) tahun, yang dibuktikan dengan kontrak kerja/surat keterangan kerja; 3. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, yang dibuktikan dengan kontrak/surat keterangan kerja; 4. Pekerjaan sejenis di bidang perencanaan/penyiapan proyek infrastruktur KPBU di instansi pemerintah, yang dibuktikan dengan kontrak kerja/surat keterangan kerja; 5. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; 6. Memiliki sertifikasi level dasar KPBU yang diakui secara nasional, yang dibuktikan dengan sertifikat/surat keterangan; 7. Tidak sedang dalam kontrak dengan unit kerja lain di Kementerian PPN/Bappenas; 8. Diutamakan konsultan dalam negeri, yang dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk (KTP); 9. Memiliki Nomor Pokok Wajib Pajak (NPWP); dan 10. Dapat menerima sistem pembayaran gaji sesuai dengan peraturan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2063401);
