INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65313155', 65313155, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Penguatan Tata Kelola Pengadaan Barang dan Jasa APBN maupun PHLN', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 150000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Menganalisis kebutuhan pengadaan barang dan jasa yang diperlukan, agar dapat tersusun jadwal pemenuhan kebutuhan barang/jasa yang tepat waktu, baik untuk pengadaan yang bersumber dari APBN maupun PHLN di lingkup Direktorat Pembiayaan Strategis dan Inovatif; 2. Melakukan reviu Kerangka Acuan Kerja dan Rencana Anggaran Biaya pengadaan barang/jasa yang akan dilaksanakan untuk dan memberikan masukan-masukan dengan mengacu pada ketentuan peraturan pengadaan barang dan jasa yang berlaku, baik untuk pengadaan yang bersumber dari APBN maupun PHLN di lingkup Direktorat Pembiayaan Strategis dan Inovatif; 3. Melakukan reviu dan koreksi terhadap draft dokumen laporan hasil pelaksanaan pengadaan, baik untuk pengadaan yang besumber dari APBN maupun PHLN dilingkup Direktorat Pembiayaan strategis dan inovatif. 4. Melakukan koordinasi dengan pihak terkait dalam persiapan pelaksaaan kebutuhan barang dan jasa yang dilakukan melalui mekanisme seleksi/tender/ pengadaan langsung di lingkup Direktorat Pembiayaan Strategis dan Inovatif; 5. Melakukan reviu bersama PIC kegiatan terhadap dokumen hasil pelaksanaan pekerjaan yang dilakukan oleh penyedia barang dan jasa sebelum pengajuan kepada tim Sesdep/PPK; 6. Melakukan monitoring dan evaluasi terhadap pelaksanaan pekerjaan yang berjalan dengan kesesuaian timeline yang telah direncanakan; 7. Memberikan saran-saran dalam penyusunan tanggapan saat proses audit internal maupun external untuk pengadaan barang dan jasa di lingkup Direktorat Pembiayaan Strategis dan Inovatif; 8. Melakukan evaluasi hasil pelaksanaan pengadaan barang dan jasa untuk pemetaan terhadap kendala dalam proses pelaksanaan atas tahun Anggaran berjalan, dan memberikan masukan-masukan perbaikan pelaksanaan pengadaan barang dan jasa ditahun mendatang untuk pengadaan yang bersumber dari APBN maupun PHLN dilingkup Direktorat Pembiayaan Strategis dan Inovatif.', 'maupun PHLN merupakan individu yang memiliki kualifikasi sebagai berikut: 1. Pendidikan minimal Sarjana (S1) di bidang Ekonomi/Manajemen yang dibuktikan dengan ijazah; 2. Memiliki pengalaman minimal 5 (lima) tahun, yang dibuktikan dengan kontrak/surat keterangan kerja; 3. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik dilingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, yang dibuktikan dengan kontrak/surat keterangan kerja; 4. Pekerjaan sejenis di bidang penyiapan dokumen proses Pengadaan Barang/Jasa di instansi pemerintah, yang dibuktikan dengan kontrak kerja/surat keterangan kerja; 5. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran 6. Memiliki Sertifikasi Pengadaan Barang/Jasa yang dikeluarkan oleh Lembaga Kebijakan Pengadaan Barang/Jasa (LKPP); 7. Tidak sedang dimasukkan dalam daftar hitam konsultan di lingkungan Kementerian PPN/Bappenas; 8. Diutamakan Konsultan Individu dalam negeri (dibuktikan dengan identitas kewarganegaan Indonesia seperti Kartu Tanda Penduduk; 9. Tidak sedang dalam kontrak dengan unit kerja lain di Kementerian PPN/Bappenas; 10. Memiliki Nomor Pokok Wajib Pajak (NPWP); 11. Dapat menerima sistem pembayaran gaji sesuai dengan peraturan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2065330);
