INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65315544', 65315544, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'TENAGA JASA KONSULTAN PENYUSUNAN REKOMENDASI KEBIJAKAN, DIREKTORAT KESEHATAN DAN GIZI MASYARAKAT', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Melakukan pemutakhiran data secara berkala untuk data kesehatan. 2. Koordinasi dengan berbagai pihak terkait kebutuhan data kesehatan dan aspek lain yang mendukung kesehatan dan gizi masyarakat untuk melakukan analisis, proyeksi dan evaluasi. 3. Merumuskan rekomendasi berbasis data untuk penguatan tata kelola, efektivitas pelaksanaan, dan keberlanjutan program khususnya peningkatan status kesehatan dan gizi masyarakat. 4. Memberikan pelatihan analisis data.', '1. Pendidikan minimal S2 di bidang Statistik/ Aktuaria/ Matematika /Ilmu Ekonomi/ Kesehatan Masyarakat/ Statistik/ Ilmu Komputer/ Data Science/ Teknik Industri. Dibuktikan dengan Ijazah. 2. Memiliki pengalaman kerja minimal 5 tahun dalam analisis data/ pengembangan dashboard/ pengelolaan sistem manajemen data bidang kesehatan/ sosial/ pendidikan/ kemiskinan/ pemberdayaan masyarakat. Dibuktikan dengan surat keterangan kerja/ surat referensi/ kontrak kerja/ sertifikat. 3. Menguasai tools visualisasi data seperti Tableau/ Google Data Studio/ Power BI. Dibuktikan dengan hasil visualisasi data yang pernah dikerjakan/ hasil analisis data/ hasil publikasi/ hasil artikel. 4. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak. 5. Memiliki pekerjaan sejenis terkait bidang kesehatan/ data analis/ manajemen/ data researcher yang dibuktikan dengan surat keterangan kerja/ surat referensi/ kontrak kerja/ sertifikat. 6. Mempunyai status valid keterangan wajib pajak berdasarkan hasil konfirmasi status wajib pajak. 7. Diutamakan Tenaga Pendukung dalam negeri yang dibuktikan dengan identitas kewarganegaraan Indonesia sebagai Kartu Tanda Penduduk.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2069361);
